<template>
  <div class="page">
    <div class="page-header"><div><div class="page-title">运营日清总览</div><div class="page-note">统计范围只包括当前在用的非仓库铺位。</div></div><el-date-picker v-model="date" type="date" value-format="YYYY-MM-DD" :clearable="false" @change="load"/></div>
    <div class="cards" v-loading="loading"><el-card><div class="value">{{num(summary.expectedCount)}}</div><div>应提交</div></el-card><el-card><div class="value success">{{num(summary.submittedCount)}}</div><div>已提交</div></el-card><el-card><div class="value danger">{{num(summary.missingCount)}}</div><div>未提交</div></el-card><el-card><div class="value warning">{{num(summary.abnormalCount)}}</div><div>异常</div></el-card><el-card><div class="value">{{num(summary.unassignedCount)}}</div><div>未分配责任商管</div></el-card></div>
    <el-card v-if="managerSummary.length" class="section"><template #header>责任商管完成情况</template><el-table :data="managerSummary" border><el-table-column prop="managerName" label="责任商管"/><el-table-column prop="expectedCount" label="应提交"/><el-table-column prop="submittedCount" label="已提交"/><el-table-column prop="missingCount" label="未提交"><template #default="{row}"><b class="danger">{{row.missingCount}}</b></template></el-table-column><el-table-column prop="abnormalCount" label="异常"/></el-table></el-card>
    <el-card class="section"><template #header><div class="section-title"><span>铺位日清明细</span><el-radio-group v-model="filter" size="small"><el-radio-button value="ALL">全部</el-radio-button><el-radio-button value="MISSING">未提交</el-radio-button><el-radio-button value="ABNORMAL">异常</el-radio-button></el-radio-group></div></template><el-table :data="filtered" border><el-table-column prop="stallCode" label="铺位" width="110"/><el-table-column prop="floorName" label="楼层" width="90"/><el-table-column prop="merchantName" label="商户" min-width="160"/><el-table-column prop="businessType" label="业态" width="110"/><el-table-column prop="managerName" label="责任商管" width="110"><template #default="{row}">{{row.managerName||'未分配'}}</template></el-table-column><el-table-column prop="managerPhone" label="联系电话" width="125"><template #default="{row}">{{row.managerPhone||'-'}}</template></el-table-column><el-table-column label="提交状态" width="100"><template #default="{row}"><el-tag :type="!row.recordId?'danger':row.status==='ABNORMAL'?'warning':'success'">{{!row.recordId?'未提交':row.status==='ABNORMAL'?'异常':'正常'}}</el-tag></template></el-table-column><el-table-column prop="submitterName" label="提交人" width="100"><template #default="{row}">{{row.submitterName||'-'}}</template></el-table-column><el-table-column prop="exceptionDescription" label="异常说明" min-width="170"><template #default="{row}">{{row.exceptionDescription||'-'}}</template></el-table-column><el-table-column label="提交时间" width="175"><template #default="{row}">{{formatDateTime(row.submittedAt)}}</template></el-table-column></el-table></el-card>
  </div>
</template>
<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{operationDashboardApi}from'@/api/operation';import{formatDateTime}from'@/utils/format'
const today=()=>{const d=new Date();if(d.getHours()<9)d.setDate(d.getDate()-1);const p=(n:number)=>String(n).padStart(2,'0');return`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`}
const date=ref(today()),loading=ref(false),summary=ref<any>({}),details=ref<any[]>([]),managerSummary=ref<any[]>([]),filter=ref('ALL')
const num=(v:any)=>Number(v)||0;const filtered=computed(()=>filter.value==='MISSING'?details.value.filter(x=>!x.recordId):filter.value==='ABNORMAL'?details.value.filter(x=>x.status==='ABNORMAL'):details.value)
async function load(){loading.value=true;try{const r:any=await operationDashboardApi.get(date.value);summary.value=r.summary||{};details.value=r.details||[];managerSummary.value=r.managerSummary||[]}finally{loading.value=false}}onMounted(load)
</script>
<style scoped>.page-note{color:#909399;margin-top:6px;font-size:13px}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.cards .el-card{text-align:center}.value{font-size:30px;font-weight:700;margin-bottom:6px}.success{color:#67c23a}.danger{color:#f56c6c}.warning{color:#e6a23c}.section{margin-top:14px}.section-title{display:flex;justify-content:space-between;align-items:center}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.page-header{align-items:flex-start}.section{overflow-x:auto}}</style>
